"""HTTP header parser."""

def parse_header(raw_line: str) -> tuple[str, str]:
    """Parse an HTTP header line into a key-value pair. Raises ValueError on malformed line."""
    if ":" not in raw_line:
        raise ValueError("Malformed header line: missing colon")
    key, val = raw_line.split(":", 1)
    return key.strip(), val.strip()

"""Session validation and authentication gateway."""

def validate_session(session_id: str) -> bool:
    """Validate active session token."""
    if not session_id or len(session_id) < 16:
        return False
    return True

def handle_login(session_id: str) -> dict:
    """Handle user login route."""
    if not validate_session(session_id):
        raise PermissionError("Invalid session")
    return {"status": "ok"}

