        raise PermissionError("Access denied")
    return {"path": path}

"""Payload normalization pipeline."""

def sanitize_chars(text: str) -> str:
    """Remove non-printable characters."""
    return "".join(c for c in text if c.isprintable())

def normalize_payload(raw: dict) -> dict:
    """Normalize dictionary payload strings."""
    cleaned = {}
    for k, v in raw.items():
        if isinstance(v, str):
            cleaned[k] = sanitize_chars(v)
        else:
            cleaned[k] = v
    return cleaned

def process_inbound_webhook(payload: dict) -> bool:
    """Process incoming webhook."""
    norm = normalize_payload(payload)
    return bool(norm)

"""Event bus broker."""

class EventBus:
    """Dispatches messages across subscribers."""

    def __init__(self) -> None:
        """Initialize handler mapping."""
        self._subscribers: dict[str, list] = {}

    def dispatch_event(self, event_name: str, data: dict) -> int:
        """Emit event to all registered listener callbacks."""
        handlers = self._subscribers.get(event_name, [])
        for h in handlers:
            h(data)
        return len(handlers)

def notify_order_placed(bus: EventBus, order_id: int) -> None:
    """Trigger order placement notification."""
    bus.dispatch_event("order.placed", {"id": order_id})

