def apply_discount(order, code):
    total = order["total"]
    if code is None:
        return total
    if code.startswith("PCT"):
        total = total * (1 - int(code[3:]) / 100)
    elif code.startswith("FLAT"):
        total = total - int(code[4:])
    elif code == "FREESHIP":
        total = total - order.get("shipping", 0)
    if total < 0:
        total = 0
    return round(total, 2)


def checkout(order, code):
    return {"charged": apply_discount(order, code)}


def preview_total(order, code):
    return apply_discount(order, code)


def reprice_cart(cart, code):
    return [apply_discount(o, code) for o in cart]

"""Application configuration loading."""

import json
import os


def load_config(path: str, env: str = "prod") -> dict:
    """Load the JSON config section for one environment."""
    if not os.path.exists(path):
        return {"env": env}
    with open(path, encoding="utf-8") as handle:
        data = json.load(handle)
    section = data.get(env)
    if section is None:
        raise KeyError(f"Missing config section {env}")
    return section


def database_url(path: str) -> str:
    """Return the database URL from config."""
    return load_config(path)["database_url"]


def cache_ttl(path: str) -> int:
    """Return the cache TTL in seconds."""
    return int(load_config(path).get("cache_ttl", 60))


def feature_enabled(path: str, name: str) -> bool:
    """Return True when a feature flag is on."""
    return name in load_config(path).get("features", [])


def staging_settings(path: str) -> dict:
    """Load the staging section."""
    return load_config(path, env="staging")

import re


def slugify(text):
    text = text.strip().lower()
    if not text:
        return "untitled"
    return re.sub("[^a-z0-9]+", "-", text).strip("-")


def make_post_url(title, post_id):
    return "/posts/%s-%s" % (post_id, slugify(title))


def make_tag_url(tag):
    return "/tags/" + slugify(tag)

class Inventory:
    def __init__(self):
        self.stock = {}
        self.reserved = {}

    def available(self, sku):
        return self.stock.get(sku, 0) - self.reserved.get(sku, 0)

    def reserve(self, sku, qty):
        if qty <= 0:
            raise ValueError("qty must be positive")
        if sku not in self.stock:
            raise KeyError(sku)
        if self.available(sku) < qty:
            return False
        self.reserved[sku] = self.reserved.get(sku, 0) + qty
        return True

    def release(self, sku, qty):
        current = self.reserved.get(sku, 0)
        self.reserved[sku] = max(0, current - qty)

def next_run(schedule, now):
    hour, minute = schedule["hour"], schedule["minute"]
    days = schedule.get("days") or list(range(7))
    for offset in range(8):
        day = (now["weekday"] + offset) % 7
        if day not in days:
            continue
        if offset == 0 and (hour, minute) <= (now["hour"], now["minute"]):
            continue
        return {"days_ahead": offset, "hour": hour, "minute": minute}
    return None

"""Date parsing helpers."""

from datetime import date


def parse_iso_date(value: str) -> date | None:
    """Parse a YYYY-MM-DD string; return None for empty input."""
    if not value:
        return None
    parts = value.split("-")
    if len(parts) != 3:
        raise ValueError(f"Bad date: {value}")
    year, month, day = (int(p) for p in parts)
    return date(year, month, day)


def parse_birthday(record: dict) -> date | None:
    """Read the birthday field of a user record."""
    return parse_iso_date(record.get("birthday", ""))


def parse_range(start: str, end: str) -> tuple:
    """Parse a start/end date pair."""
    return parse_iso_date(start), parse_iso_date(end)

def paginate(items: list, page: int = 1, page_size: int = 20) -> dict:
    if page < 1:
        raise ValueError("page starts at 1")
    start = (page - 1) * page_size
    chunk = items[start:start + page_size]
    has_next = start + page_size < len(items)
    return {"items": chunk, "page": page, "has_next": has_next}


def list_orders(orders: list, page: int) -> dict:
    return paginate(orders, page)


def list_users(users: list, page: int) -> dict:
    return paginate(users, page, page_size=50)

